import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int T = Integer.parseInt(st.nextToken()); while (T-- > 0) { st = new StringTokenizer(br.readLine()); int G = Integer.parseInt(st.nextToken()); StringBuilder sb = new StringBuilder(); while (G-- > 0) { st = new StringTokenizer(br.readLine()); int I = Integer.parseInt(st.nextToken()); int N = Integer.parseInt(st.nextToken()); int Q = Integer.parseInt(st.nextToken()); int half = N / 2; if (I == Q) { sb.append(half).append("\n"); } else { sb.append(N - half).append("\n"); } } System.out.print(sb.toString()); } } }